<x-filament-panels::page>@php($s=$this->stats)<style>.sa{display:flex;flex-direction:column;gap:18px}.sa-hero,.sa-panel,.sa-stat{border:1px solid rgba(124,58,237,.18);border-radius:18px;background:#fff}.sa-hero{padding:22px;background:linear-gradient(125deg,#fff,#f5f3ff,#ede9fe)}.sa-title{font-size:27px;font-weight:950;color:#111827}.sa-sub{color:#6b7280;font-size:12px}.sa-filter{display:grid;grid-template-columns:2fr 1fr 1.5fr 2fr;gap:10px;margin-top:16px}.sa-filter select,.sa-filter input{border:1px solid #ddd6fe;border-radius:10px;padding:9px;background:#fff}.sa-stats{display:grid;grid-template-columns:repeat(6,1fr);gap:10px}.sa-stat{padding:14px}.sa-stat span{font-size:9px;font-weight:900;color:#7c3aed;text-transform:uppercase}.sa-stat b{display:block;font-size:22px;color:#111827}.sa-table{overflow:auto}.sa-table table{width:100%;min-width:950px;border-collapse:collapse}.sa-table th,.sa-table td{padding:12px;border-bottom:1px solid #eee;text-align:left;font-size:10px}.sa-table th{color:#6b7280}.sa-event{padding:4px 7px;border-radius:99px;background:#ede9fe;color:#5b21b6;font-weight:850}.sa-values{max-width:260px;white-space:normal;color:#6b7280}html.dark .sa-hero,html.dark .sa-panel,html.dark .sa-stat{background:linear-gradient(145deg,#09080e,#171023);border-color:rgba(167,139,250,.24)}html.dark .sa-title,html.dark .sa-stat b,html.dark .sa-table td{color:#f8fafc}html.dark .sa-filter select,html.dark .sa-filter input{background:#100d17;color:#fff;color-scheme:dark}@media(max-width:900px){.sa-stats{grid-template-columns:repeat(3,1fr)}.sa-filter{grid-template-columns:1fr 1fr}}</style><div class="sa"><section class="sa-hero"><div class="sa-title">🛡️ Security & Activity Audit</div><div class="sa-sub">Immutable activity visibility with sensitive values automatically redacted.</div><div class="sa-filter"><select wire:model.live="constituencyId"><option value="">All Assemblies</option>@foreach($this->constituencies as $c)<option value="{{$c->id}}">{{$c->name}}</option>@endforeach</select><select wire:model.live="event"><option value="">All Events</option>@foreach(['created','updated','deleted','login','logout','login_failed'] as $e)<option value="{{$e}}">{{ucwords(str_replace('_',' ',$e))}}</option>@endforeach</select><select wire:model.live="userId"><option value="">All Users</option>@foreach($this->users as $u)<option value="{{$u->id}}">{{$u->name}}</option>@endforeach</select><input placeholder="Search activity..." wire:model.live.debounce.400ms="search"></div></section><div class="sa-stats">@foreach(['today'=>'Activities Today','logins'=>'Logins Today','failed'=>'Failed Logins','updates'=>'Updates','deletes'=>'Deletes','activeUsers'=>'Active Users'] as $k=>$l)<div class="sa-stat"><span>{{$l}}</span><b>{{number_format($s[$k])}}</b></div>@endforeach</div><section class="sa-panel sa-table"><table><thead><tr><th>Time</th><th>Event</th><th>User</th><th>Assembly</th><th>Description</th><th>Record</th><th>Changed Fields</th><th>IP</th></tr></thead><tbody>@forelse($this->logs as $log)<tr><td>{{$log->created_at->format('d M Y, h:i:s A')}}</td><td><span class="sa-event">{{$log->event}}</span></td><td>{{$log->user?->name??'System/Unknown'}}</td><td>{{$log->constituency?->name??'Global'}}</td><td>{{$log->description}}</td><td>{{class_basename($log->auditable_type??'')}} #{{$log->auditable_id}}</td><td class="sa-values">{{implode(', ',array_keys($log->new_values??[]))?:'—'}}</td><td>{{$log->ip_address??'—'}}</td></tr>@empty<tr><td colspan="8">No audit activity found.</td></tr>@endforelse</tbody></table></section></div></x-filament-panels::page>
